using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Export;using ToneCustoms.ShellStudio.Validation;using Xunit;
namespace ToneCustoms.ShellStudio.Tests;
public class CoreTests { [Fact]public void GridSnapWorks(){var v=new GeometryService().Snap(new Vec3(1.12f,.61f,.1f),.25f);Assert.Equal(1f,v.X);Assert.Equal(.5f,v.Y);Assert.Equal(0f,v.Z);}[Fact]public void WallHasExpectedType()=>Assert.Equal(SceneObjectType.Wall,new GeometryService().Wall(new Vec3()).Type);[Fact]public void EmptyProjectWarns()=>Assert.Contains(new ProjectValidator().Validate(new ShellProject()),x=>x.Area=="Geometry");[Fact]public void RoomGeneratorCreatesShell(){var items=new RoomGenerator().Generate(new Vec3(),5,5).ToList();Assert.Equal(6,items.Count);Assert.Equal(4,items.Count(x=>x.Type==SceneObjectType.Wall));}[Fact]public void WallOpeningPersists(){var p=new ShellProject();var w=new GeometryService().Wall(new Vec3());p.Objects.Add(w);new WallOpeningService().Add(p,w,0,1,2,0,true);Assert.Single(p.WallOpenings);}[Fact]public void BuilderCreatesManifest(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString());var p=new ShellProject{Name="test_shell"};var r=new FiveMResourceBuilder().Prepare(p,root);Assert.True(File.Exists(Path.Combine(r,"fxmanifest.lua")));Directory.Delete(root,true);} }
